/* eslint-disable */
/**
 * Regenerate lib/educo-ui/stock-photos-curated.generated.ts — the bundled no-key photo library — from the
 * official Unsplash API. This is the repeatable/CI-friendly path (the initial set was crawled from the site).
 *
 *   UNSPLASH_ACCESS_KEY=xxxxx  node scripts/gen-stock-photos.js
 *
 * Get a free key at https://unsplash.com/developers. To refresh regularly, run this on a schedule (e.g. a
 * GitHub Actions cron with the key as a repo secret) and commit the regenerated file — NOT an agent cron.
 * Photos are hotlinked from Unsplash's CDN (Unsplash License: free to use, incl. commercially; attribution
 * appreciated — we keep the photographer name + link per photo).
 */
const fs = require("fs");
const path = require("path");

const KEY = process.env.UNSPLASH_ACCESS_KEY;
if (!KEY) {
  console.error("Missing UNSPLASH_ACCESS_KEY. Get a free key at https://unsplash.com/developers");
  process.exit(1);
}

const TOPICS = [
  "nature", "trees", "forest", "jungle", "rainforest", "ocean", "sea", "beach", "waterfall", "lake", "river", "coral reef",
  "mountains", "desert", "canyon", "sky", "clouds", "sunset", "sunrise", "aurora", "northern lights", "flowers", "autumn", "winter", "snow", "spring", "meadow",
  "animals", "wildlife", "birds", "cat", "dog", "horse", "lion", "elephant", "deer", "fox", "marine life", "fish", "whale", "dolphin", "sea turtle", "jellyfish", "shark",
  "space", "galaxy", "stars", "nebula", "city", "architecture", "minimal", "abstract", "texture", "gradient", "pattern", "food", "coffee", "business", "technology", "office", "people", "landscape", "night sky", "rain", "fog", "waves", "underwater", "tropical", "volcano", "island",
];
const PAGES = 2; // 30/page → up to 60 per topic

const title = (s) => s.split(" ").map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const seen = new Set();
  const rows = [];
  for (const topic of TOPICS) {
    for (let page = 1; page <= PAGES; page++) {
      const url = `https://api.unsplash.com/search/photos?query=${encodeURIComponent(topic)}&per_page=30&page=${page}&orientation=landscape&client_id=${KEY}`;
      try {
        const r = await fetch(url);
        if (!r.ok) { console.warn(`  ${topic} p${page}: ${r.status}`); await sleep(300); continue; }
        const j = await r.json();
        const tName = title(topic);
        for (const p of j.results || []) {
          const base = (p.urls?.raw || "").split("?")[0];
          if (!base.startsWith("https://images.unsplash.com/photo-")) continue; // free only (skip plus/premium)
          if (seen.has(base)) continue;
          seen.add(base);
          rows.push({ id: p.id, base, alt: (p.alt_description || p.description || topic).replace(/\s+/g, " ").trim().slice(0, 120), credit: p.user?.name || "", creditUrl: p.links?.html || "", topic: tName });
        }
      } catch (e) { console.warn(`  ${topic} p${page}: ${e.message}`); }
      await sleep(200); // be polite to the API
    }
    process.stdout.write(".");
  }
  const ts =
    `// AUTO-GENERATED by scripts/gen-stock-photos.js — real free photos from Unsplash (Unsplash License).\n` +
    `// Rows = base image URL + credit + topic. Regenerate: UNSPLASH_ACCESS_KEY=… node scripts/gen-stock-photos.js\n` +
    `export type CuratedPhoto = { id: string; base: string; alt: string; credit: string; creditUrl: string; topic: string };\n` +
    `export const CURATED_PHOTOS: CuratedPhoto[] = ${JSON.stringify(rows)};\n`;
  fs.writeFileSync(path.join(__dirname, "..", "lib", "educo-ui", "stock-photos-curated.generated.ts"), ts);
  console.log(`\nwrote ${rows.length} photos across ${new Set(rows.map((r) => r.topic)).size} topics`);
})();
